CREATE TABLE cb_template (id VARCHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, workflow TEXT NOT NULL, mappings TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE cb_job (id VARCHAR(36) PRIMARY KEY, template_id VARCHAR(36) NOT NULL, idempotency_key VARCHAR(128) UNIQUE, request_hash VARCHAR(64) NOT NULL, created_at BIGINT NOT NULL, FOREIGN KEY(template_id) REFERENCES cb_template(id));
CREATE TABLE cb_task (id VARCHAR(36) PRIMARY KEY, job_id VARCHAR(36) NOT NULL, ordinal_no INT NOT NULL, state VARCHAR(20) NOT NULL, workflow TEXT NOT NULL, seed BIGINT NOT NULL, prompt_id VARCHAR(36), attempt INT NOT NULL DEFAULT 0, progress INT NOT NULL DEFAULT 0, error TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, started_at BIGINT, next_run_at BIGINT NOT NULL, cancel_requested BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(job_id) REFERENCES cb_job(id), UNIQUE(job_id, ordinal_no));
CREATE INDEX cb_task_dispatch ON cb_task(state, next_run_at);
CREATE TABLE cb_event (id VARCHAR(36) PRIMARY KEY, task_id VARCHAR(36) NOT NULL, from_state VARCHAR(20), to_state VARCHAR(20) NOT NULL, reason TEXT NOT NULL, happened_at BIGINT NOT NULL, FOREIGN KEY(task_id) REFERENCES cb_task(id));
CREATE TABLE cb_attempt (id VARCHAR(36) PRIMARY KEY, task_id VARCHAR(36) NOT NULL, attempt_no INT NOT NULL, prompt_id VARCHAR(36) NOT NULL, error TEXT, started_at BIGINT NOT NULL, ended_at BIGINT, FOREIGN KEY(task_id) REFERENCES cb_task(id), UNIQUE(task_id, attempt_no));
CREATE TABLE cb_result (id VARCHAR(36) PRIMARY KEY, task_id VARCHAR(36) NOT NULL, path VARCHAR(512) NOT NULL UNIQUE, sha256 VARCHAR(64) NOT NULL, width INT NOT NULL, height INT NOT NULL, seed BIGINT NOT NULL, FOREIGN KEY(task_id) REFERENCES cb_task(id));
